/**
 * AI Studio chat turns: reading them from the DOM, matching them to stored
 * messages, and scrolling to one reliably.
 *
 * Shared by the SmartScrollbar (DOM-fed) and the DOM adapter that backs the
 * Explorer outline (store-fed).
 *
 * DOM facts this relies on (checked against the live page):
 * - Every turn of the prompt is an `ms-chat-turn#turn-<UUID>`, all present at
 *   once (no history paging). The role sits on an inner `[data-turn-role]`.
 * - The `turn-<UUID>` ids are generated by the client on every render, and the
 *   API carries no message ids, so stored messages can only be matched by position.
 * - Turn bodies are virtualised: off-screen turns keep their outer box but their
 *   text is replaced by a height placeholder.
 * - AI Studio's own scrollbar (`ms-items-scrollbar`) has one button per user turn,
 *   `#scrollbar-item-<UUID>`, whose `aria-label` is the question cut to ~40 chars.
 *   It is present even while hidden, so it is the always-available text check.
 */

export const AISTUDIO_TURN_SELECTOR = 'ms-chat-turn';
export const AISTUDIO_USER_ROLE_SELECTOR = '[data-turn-role="User"]';

export const normalizeTurnText = (s: string) => s.replace(/\s+/g, ' ').trim();

export const isUserTurn = (turn: Element) => !!turn.querySelector(AISTUDIO_USER_ROLE_SELECTOR);

export function readUserTurns(): HTMLElement[] {
  return Array.from(document.querySelectorAll<HTMLElement>(AISTUDIO_TURN_SELECTOR)).filter(
    (turn) => !!turn.id && isUserTurn(turn),
  );
}

/** Native scrollbar label for a user turn ('' when AI Studio has none). */
export function readTurnLabel(turn: HTMLElement): string {
  const uuid = turn.id.replace(/^turn-/, '');
  return document.getElementById(`scrollbar-item-${uuid}`)?.getAttribute('aria-label') ?? '';
}

/** Text of a rendered turn, minus the leading role caption ('' while virtualised). */
export function readRenderedText(turn: HTMLElement): string {
  return normalizeTurnText(
    (turn.querySelector('.turn-content') as HTMLElement | null)?.innerText ?? '',
  ).replace(/^User\s*/, '');
}

/** The label is the question cut short with a trailing ellipsis. */
export function labelPrefix(label: string): string {
  return normalizeTurnText(label).replace(/(\.{3}|…)$/, '').trim();
}

export function textsAgree(full: string, prefix: string): boolean {
  if (!prefix) return false;
  const a = normalizeTurnText(full);
  return a.startsWith(prefix) || prefix.startsWith(a);
}

// ── Jump ─────────────────────────────────────────────────────────────

/** Interval between alignment checks after a jump */
const SETTLE_INTERVAL_MS = 120;
/** Give up correcting after this many checks (~1.2s) */
const SETTLE_MAX_CHECKS = 10;
/** Consecutive aligned checks needed before the jump counts as landed */
const SETTLE_STABLE_CHECKS = 2;
/** Offset (px) still considered aligned */
const ALIGN_TOLERANCE = 4;

/**
 * Bring `turn` to the top of `scroller` and keep it there while the page settles.
 *
 * Instant, not smooth: a smooth scroll over a long distance renders every
 * virtualised turn on the way, each one changing height mid-flight, and it lands
 * short of the target. Jump, then keep re-aligning until the turns around the
 * target have rendered and the offset stays put.
 *
 * `onStep` runs before every further correction (callers use it to extend a lock
 * on their own scroll tracking). Returns a function that stops the corrections.
 */
export function scrollTurnIntoView(
  turn: HTMLElement,
  scroller: HTMLElement,
  onStep?: () => void,
): () => void {
  let cancelled = false;
  const align = () => turn.scrollIntoView({ block: 'start', behavior: 'auto' });
  align();

  let checks = 0;
  let stable = 0;
  const settle = () => {
    if (cancelled || !turn.isConnected) return;
    const offset = turn.getBoundingClientRect().top - scroller.getBoundingClientRect().top;
    if (Math.abs(offset) > ALIGN_TOLERANCE) {
      stable = 0;
      align();
    } else if (++stable >= SETTLE_STABLE_CHECKS) {
      return;
    }
    if (++checks < SETTLE_MAX_CHECKS) {
      onStep?.();
      setTimeout(settle, SETTLE_INTERVAL_MS);
    }
  };
  setTimeout(settle, SETTLE_INTERVAL_MS);

  return () => {
    cancelled = true;
  };
}
